INSERT INTO public.language_passages (id, language, level, order_index, title_ru, topic_emoji, passage, passage_ru, questions) VALUES
(gen_random_uuid(), 'es', 'A2', 1, 'En el hotel', '🏨', $P$Marta llega al hotel por la tarde. En la recepción, una mujer le da la llave de su habitación. La habitación está en el tercer piso. Es pequeña pero limpia, con una cama grande y una ventana al parque. El desayuno es a las ocho de la mañana. Marta deja la maleta, toma una ducha y baja al restaurante del hotel. Tiene hambre y pide una sopa y un café. Después, sale a caminar por el centro de la ciudad.$P$, $R$Марта приезжает в отель во второй половине дня. На ресепшене женщина даёт ей ключ от номера. Номер на третьем этаже. Он маленький, но чистый, с большой кроватью и окном в парк. Завтрак в восемь утра. Марта оставляет чемодан, принимает душ и спускается в ресторан отеля. Она голодна и заказывает суп и кофе. Потом выходит прогуляться по центру города.$R$, $Q$[{"q_ru": "На каком этаже номер Марты?", "options": ["На третьем", "На первом", "На восьмом"], "correct": 0}, {"q_ru": "Во сколько завтрак?", "options": ["В восемь утра", "В три дня", "В семь вечера"], "correct": 0}, {"q_ru": "Что заказывает Марта в ресторане?", "options": ["Суп и кофе", "Пиццу", "Только воду"], "correct": 0}]$Q$),
(gen_random_uuid(), 'es', 'A2', 2, 'Un día en la ciudad', '🏙️', $P$Hoy es sábado y Pablo no trabaja. Por la mañana va al mercado y compra fruta y pan. Después visita un museo en el centro. La entrada cuesta cinco euros. Por la tarde se encuentra con un amigo en un café cerca de la plaza. Hablan mucho y beben té. Más tarde van al cine a ver una película. Pablo vuelve a casa por la noche, cansado pero feliz.$P$, $R$Сегодня суббота, и Пабло не работает. Утром он идёт на рынок и покупает фрукты и хлеб. Потом посещает музей в центре. Вход стоит пять евро. Днём он встречается с другом в кафе рядом с площадью. Они много разговаривают и пьют чай. Позже идут в кино смотреть фильм. Пабло возвращается домой вечером, уставший, но счастливый.$R$, $Q$[{"q_ru": "Что покупает Пабло на рынке?", "options": ["Фрукты и хлеб", "Книги", "Одежду"], "correct": 0}, {"q_ru": "Сколько стоит вход в музей?", "options": ["Пять евро", "Десять евро", "Ничего"], "correct": 0}, {"q_ru": "Каким Пабло возвращается домой?", "options": ["Уставшим, но счастливым", "Грустным", "Голодным"], "correct": 0}]$Q$),
(gen_random_uuid(), 'es', 'A2', 3, 'En el restaurante', '🍽️', $P$Ana y Luis van a un restaurante italiano para cenar. El camarero les da el menú. Ana pide pasta y una ensalada; Luis pide pescado con verduras. Para beber, piden agua y vino. La comida está muy buena. Al final, Luis pide la cuenta. Son treinta euros. Deja una propina para el camarero. Ana dice que quiere volver otro día. Salen del restaurante contentos.$P$, $R$Ана и Луис идут в итальянский ресторан поужинать. Официант даёт им меню. Ана заказывает пасту и салат; Луис заказывает рыбу с овощами. Из напитков заказывают воду и вино. Еда очень вкусная. В конце Луис просит счёт. Это тридцать евро. Он оставляет чаевые официанту. Ана говорит, что хочет прийти ещё раз. Они выходят из ресторана довольные.$R$, $Q$[{"q_ru": "Что заказывает Луис?", "options": ["Рыбу с овощами", "Пасту", "Пиццу"], "correct": 0}, {"q_ru": "Сколько составляет счёт?", "options": ["Тридцать евро", "Пятнадцать евро", "Пятьдесят евро"], "correct": 0}, {"q_ru": "Что говорит Ана в конце?", "options": ["Хочет прийти ещё раз", "Что было невкусно", "Что устала"], "correct": 0}]$Q$),
(gen_random_uuid(), 'fr', 'A2', 1, 'À l''hôtel', '🏨', $P$Sophie arrive à l'hôtel le soir. À la réception, un homme lui donne la clé de sa chambre. La chambre est au deuxième étage. Elle est petite mais confortable, avec un grand lit et une fenêtre sur la rue. Le petit déjeuner est à sept heures et demie. Sophie pose sa valise, prend une douche et descend au restaurant. Elle a faim et commande une salade et un thé. Ensuite, elle sort marcher dans le centre-ville.$P$, $R$Софи приезжает в отель вечером. На ресепшене мужчина даёт ей ключ от номера. Номер на втором этаже. Он маленький, но удобный, с большой кроватью и окном на улицу. Завтрак в половине восьмого. Софи ставит чемодан, принимает душ и спускается в ресторан. Она голодна и заказывает салат и чай. Потом выходит прогуляться по центру города.$R$, $Q$[{"q_ru": "На каком этаже номер?", "options": ["На втором", "На первом", "На седьмом"], "correct": 0}, {"q_ru": "Что заказывает Софи в ресторане?", "options": ["Салат и чай", "Рыбу", "Кофе"], "correct": 0}, {"q_ru": "Что делает Софи после ужина?", "options": ["Идёт гулять по центру", "Спит", "Звонит домой"], "correct": 0}]$Q$),
(gen_random_uuid(), 'fr', 'A2', 2, 'Une journée en ville', '🏙️', $P$C'est dimanche et Marc ne travaille pas. Le matin, il va au marché et achète des fruits et du fromage. Ensuite, il visite un musée près de la place. Le billet coûte huit euros. L'après-midi, il retrouve une amie dans un café. Ils parlent beaucoup et boivent un café. Plus tard, ils vont au parc et marchent une heure. Le soir, Marc rentre à la maison, fatigué mais content.$P$, $R$Сегодня воскресенье, и Марк не работает. Утром он идёт на рынок и покупает фрукты и сыр. Потом посещает музей рядом с площадью. Билет стоит восемь евро. Днём он встречается с подругой в кафе. Они много разговаривают и пьют кофе. Позже идут в парк и гуляют час. Вечером Марк возвращается домой, уставший, но довольный.$R$, $Q$[{"q_ru": "Что покупает Марк на рынке?", "options": ["Фрукты и сыр", "Хлеб и молоко", "Одежду"], "correct": 0}, {"q_ru": "Сколько стоит билет в музей?", "options": ["Восемь евро", "Пять евро", "Десять евро"], "correct": 0}, {"q_ru": "Куда они идут позже?", "options": ["В парк", "В кино", "Домой"], "correct": 0}]$Q$),
(gen_random_uuid(), 'fr', 'A2', 3, 'Au restaurant', '🍽️', $P$Julie et Paul vont au restaurant pour dîner. Le serveur leur donne le menu. Julie commande une soupe et un poisson; Paul prend de la viande avec des légumes. Ils boivent de l'eau et du vin. Le repas est délicieux. À la fin, Paul demande l'addition. Cela fait quarante euros. Il laisse un pourboire pour le serveur. Julie veut revenir bientôt. Ils prennent un taxi parce qu'il pleut.$P$, $R$Жюли и Поль идут в ресторан поужинать. Официант даёт им меню. Жюли заказывает суп и рыбу; Поль берёт мясо с овощами. Они пьют воду и вино. Еда очень вкусная. В конце Поль просит счёт. Это сорок евро. Он оставляет чаевые официанту. Жюли хочет вернуться скоро. Они берут такси, потому что идёт дождь.$R$, $Q$[{"q_ru": "Что заказывает Жюли?", "options": ["Суп и рыбу", "Мясо", "Пиццу"], "correct": 0}, {"q_ru": "Сколько составляет счёт?", "options": ["Сорок евро", "Двадцать евро", "Шестьдесят евро"], "correct": 0}, {"q_ru": "Почему они берут такси?", "options": ["Идёт дождь", "Поздно", "Далеко"], "correct": 0}]$Q$),
(gen_random_uuid(), 'de', 'A2', 1, 'Im Hotel', '🏨', $P$Anna kommt am Abend im Hotel an. An der Rezeption gibt ihr eine Frau den Schlüssel für ihr Zimmer. Das Zimmer ist im dritten Stock. Es ist klein, aber sauber, mit einem großen Bett und einem Fenster zum Park. Das Frühstück ist um acht Uhr. Anna stellt den Koffer ab, duscht und geht ins Restaurant. Sie hat Hunger und bestellt eine Suppe und einen Tee. Danach geht sie im Stadtzentrum spazieren.$P$, $R$Анна приезжает в отель вечером. На ресепшене женщина даёт ей ключ от номера. Номер на третьем этаже. Он маленький, но чистый, с большой кроватью и окном в парк. Завтрак в восемь часов. Анна ставит чемодан, принимает душ и идёт в ресторан. Она голодна и заказывает суп и чай. Потом идёт гулять по центру города.$R$, $Q$[{"q_ru": "На каком этаже номер?", "options": ["На третьем", "На первом", "На восьмом"], "correct": 0}, {"q_ru": "Во сколько завтрак?", "options": ["В восемь часов", "В три", "В семь"], "correct": 0}, {"q_ru": "Что заказывает Анна?", "options": ["Суп и чай", "Рыбу", "Кофе"], "correct": 0}]$Q$),
(gen_random_uuid(), 'de', 'A2', 2, 'Ein Tag in der Stadt', '🏙️', $P$Heute ist Samstag und Thomas arbeitet nicht. Am Morgen geht er auf den Markt und kauft Obst und Brot. Dann besucht er ein Museum im Zentrum. Der Eintritt kostet sieben Euro. Am Nachmittag trifft er einen Freund in einem Café am Platz. Sie reden viel und trinken Kaffee. Später gehen sie ins Kino und sehen einen Film. Am Abend fährt Thomas mit der U-Bahn nach Hause, müde aber glücklich.$P$, $R$Сегодня суббота, и Томас не работает. Утром он идёт на рынок и покупает фрукты и хлеб. Потом посещает музей в центре. Вход стоит семь евро. Днём он встречает друга в кафе на площади. Они много разговаривают и пьют кофе. Позже идут в кино и смотрят фильм. Вечером Томас едет домой на метро, уставший, но счастливый.$R$, $Q$[{"q_ru": "Что покупает Томас на рынке?", "options": ["Фрукты и хлеб", "Сыр", "Одежду"], "correct": 0}, {"q_ru": "Сколько стоит вход?", "options": ["Семь евро", "Десять евро", "Ничего"], "correct": 0}, {"q_ru": "Как Томас едет домой?", "options": ["На метро", "На такси", "Пешком"], "correct": 0}]$Q$),
(gen_random_uuid(), 'de', 'A2', 3, 'Im Restaurant', '🍽️', $P$Lena und Max gehen ins Restaurant zum Abendessen. Der Kellner gibt ihnen die Speisekarte. Lena bestellt Fisch mit Gemüse; Max nimmt Fleisch und einen Salat. Sie trinken Wasser und Wein. Das Essen ist sehr gut. Am Ende bittet Max um die Rechnung. Das macht fünfunddreißig Euro. Er gibt dem Kellner ein Trinkgeld. Lena möchte bald wiederkommen. Sie gehen zu Fuß nach Hause, weil sie in der Nähe wohnen.$P$, $R$Лена и Макс идут в ресторан на ужин. Официант даёт им меню. Лена заказывает рыбу с овощами; Макс берёт мясо и салат. Они пьют воду и вино. Еда очень вкусная. В конце Макс просит счёт. Это тридцать пять евро. Он даёт официанту чаевые. Лена хочет скоро вернуться. Они идут домой пешком, потому что живут рядом.$R$, $Q$[{"q_ru": "Что заказывает Лена?", "options": ["Рыбу с овощами", "Мясо", "Пиццу"], "correct": 0}, {"q_ru": "Сколько составляет счёт?", "options": ["Тридцать пять евро", "Двадцать евро", "Пятьдесят евро"], "correct": 0}, {"q_ru": "Почему они идут пешком?", "options": ["Живут рядом", "Нет денег", "Идёт снег"], "correct": 0}]$Q$)
