-- 148_es_de_fr_reading_a2.sql
-- Тексты для чтения A2 (es/de/fr), по 3 на язык + вопросы. Идемпотентно (ON CONFLICT).
ALTER TABLE public.language_passages DROP CONSTRAINT IF EXISTS language_passages_language_check;
ALTER TABLE public.language_passages ADD  CONSTRAINT language_passages_language_check CHECK (language IN ('en','it','es','de','fr'));

ON CONFLICT (language, level, order_index) DO UPDATE SET title_ru=EXCLUDED.title_ru, topic_emoji=EXCLUDED.topic_emoji, passage=EXCLUDED.passage, passage_ru=EXCLUDED.passage_ru, questions=EXCLUDED.questions;
